def esc(s: str) -> str:
    return s.replace("\\", "\\\\").replace("'", "\\'").replace("$", "\\$")


def main():
    keys = [k for k, _, _ in S]
    dup = {k for k in keys if keys.count(k) > 1}
    assert not dup, f"duplicate keys: {dup}"
    out = Path(__file__).resolve().parents[1] / "lib" / "core" / "l10n"
    for lang, idx in (("en", 1), ("bn", 2)):
        lines = [f"// Generated by tool/strings.py - edit there, not here.", "// ignore_for_file: lines_longer_than_80_chars",
                 "", f"const strings{lang.capitalize()} = <String, String>{{"]
        lines += [f"  '{esc(row[0])}': '{esc(row[idx])}'," for row in S]
        lines.append("};\n")
        (out / f"strings_{lang}.dart").write_text("\n".join(lines), encoding="utf-8")
    print(f"{len(S)} strings written")


if __name__ == "__main__":
    main()
